#!/usr/bin/env python3
"""Check the house rules AGENTS.md states that no other linter enforces.

Usage: python3 tools/check_rules.py (make lint). Prints path:line: problem and exits 1 on any.
- No em dashes in tracked text, except the generated CHANGELOG.md and recorded server replies.
- Every action a workflow uses is pinned by a full commit SHA, with its version in a comment.
"""
import pathlib, re, subprocess, sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
EM_DASH = "\u2014"
# Generated by release-please, or recorded verbatim from the Scenario MCP server.
EM_DASH_EXEMPT = ("CHANGELOG.md", "tests/fixtures/")
WORKFLOW_FILES = re.compile(r"^\.github/(workflows/[^/]+\.ya?ml|actions/.+/action\.ya?ml)$")
USES = re.compile(r"^\s*(?:-\s+)?uses:\s*(\S+)(.*)$")
PINNED = re.compile(r"^[\w.-]+/[\w./-]+@[0-9a-f]{40}$")
VERSION_COMMENT = re.compile(r"^\s+#\s*v?\d")


def em_dash_problems(path: str, text: str) -> list[str]:
    if path.startswith(EM_DASH_EXEMPT):
        return []
    return [f"{path}:{n}: em dash; use a comma, a colon, parentheses or two sentences"
            for n, line in enumerate(text.splitlines(), 1) if EM_DASH in line]


def pin_problems(path: str, text: str) -> list[str]:
    if not WORKFLOW_FILES.match(path):
        return []
    out = []
    for n, line in enumerate(text.splitlines(), 1):
        match = USES.match(line)
        if not match:
            continue
        ref, rest = match.group(1).strip("'\""), match.group(2)
        if ref.startswith(("./", "docker://")):
            continue
        if not PINNED.match(ref):
            out.append(f"{path}:{n}: pin {ref} to a full commit SHA")
        elif not VERSION_COMMENT.match(rest):
            out.append(f"{path}:{n}: add the version after the SHA, as `# vX.Y.Z`")
    return out


def main() -> int:
    paths = subprocess.run(["git", "ls-files"], cwd=ROOT, capture_output=True, text=True, check=True).stdout.splitlines()
    problems = []
    for path in paths:
        if path.startswith(("addons/gut/", "addons/agentkit/")):
            continue  # vendored, never edited by hand
        try:
            text = (ROOT / path).read_text(encoding="utf-8")
        except (UnicodeDecodeError, FileNotFoundError, IsADirectoryError):
            continue  # binary, or a symlink to a folder
        problems += em_dash_problems(path, text) + pin_problems(path, text)
    for problem in problems:
        print(problem)
    return 1 if problems else 0


if __name__ == "__main__":
    sys.exit(main())
